const STYLE_CSS = "/* ==========================================================================\n   Student Task Management Application - 2-Color Design System\n   Primary Color: Vibrant Orange (#f97316)\n   Secondary / Contrast Color: Deep Slate (#0f172a)\n   ========================================================================== */\n\n:root {\n  /* Color 1: Primary Orange */\n  --primary: #f97316;\n  --primary-hover: #ea580c;\n  --primary-active: #c2410c;\n  --primary-light: #fff7ed;\n  --primary-border: #fed7aa;\n  --primary-text: #c2410c;\n  --primary-shadow: rgba(249, 115, 22, 0.24);\n\n  /* Color 2: Deep Slate & Neutrals */\n  --slate-900: #0f172a;\n  --slate-800: #1e293b;\n  --slate-700: #334155;\n  --slate-600: #475569;\n  --slate-500: #64748b;\n  --slate-300: #cbd5e1;\n  --slate-200: #e2e8f0;\n  --slate-100: #f1f5f9;\n  --slate-50: #f8fafc;\n  --white: #ffffff;\n\n  /* Semantic Typography & Surfaces */\n  --bg-page: #f8fafc;\n  --bg-card: #ffffff;\n  --text-main: var(--slate-900);\n  --text-body: var(--slate-700);\n  --text-muted: var(--slate-500);\n  --border-color: var(--slate-200);\n  --border-focus: var(--primary);\n\n  /* Radius & Shadows */\n  --radius-sm: 6px;\n  --radius-md: 10px;\n  --radius-lg: 14px;\n  --radius-xl: 20px;\n  --shadow-sm: 0 1px 2px 0 rgba(15, 23, 42, 0.05);\n  --shadow-md: 0 4px 6px -1px rgba(15, 23, 42, 0.07), 0 2px 4px -2px rgba(15, 23, 42, 0.05);\n  --shadow-lg: 0 10px 15px -3px rgba(15, 23, 42, 0.08), 0 4px 6px -4px rgba(15, 23, 42, 0.04);\n  --shadow-modal: 0 20px 25px -5px rgba(15, 23, 42, 0.15), 0 8px 10px -6px rgba(15, 23, 42, 0.1);\n  --transition: all 0.2s cubic-bezier(0.4, 0, 0.2, 1);\n}\n\n/* Base Reset */\n*, *::before, *::after {\n  box-sizing: border-box;\n  margin: 0;\n  padding: 0;\n}\n\nbody {\n  font-family: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;\n  background-color: var(--bg-page);\n  color: var(--text-main);\n  min-height: 100vh;\n  line-height: 1.5;\n  -webkit-font-smoothing: antialiased;\n}\n\n/* Layout */\n.app-layout {\n  max-width: 1200px;\n  margin: 0 auto;\n  padding: 32px 24px 60px 24px;\n}\n\n/* Header */\n.app-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  margin-bottom: 32px;\n  padding-bottom: 24px;\n  border-bottom: 1px solid var(--border-color);\n  gap: 20px;\n  flex-wrap: wrap;\n}\n\n.header-branding {\n  display: flex;\n  align-items: center;\n  gap: 16px;\n}\n\n.brand-icon {\n  width: 52px;\n  height: 52px;\n  background-color: var(--primary);\n  color: var(--white);\n  border-radius: var(--radius-md);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 24px;\n  box-shadow: 0 4px 12px var(--primary-shadow);\n  flex-shrink: 0;\n}\n\n.brand-title {\n  font-size: 26px;\n  font-weight: 800;\n  color: var(--slate-900);\n  letter-spacing: -0.025em;\n  line-height: 1.2;\n}\n\n.brand-subtitle {\n  font-size: 14px;\n  color: var(--text-muted);\n  font-weight: 400;\n  margin-top: 4px;\n}\n\n.header-actions {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n}\n\n/* Buttons */\n.btn {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 8px;\n  font-family: inherit;\n  font-size: 14px;\n  font-weight: 600;\n  padding: 10px 18px;\n  border-radius: var(--radius-md);\n  border: 1px solid transparent;\n  cursor: pointer;\n  transition: var(--transition);\n  text-decoration: none;\n  white-space: nowrap;\n}\n\n.btn-primary {\n  background-color: var(--primary);\n  color: var(--white);\n  box-shadow: 0 2px 6px var(--primary-shadow);\n}\n\n.btn-primary:hover {\n  background-color: var(--primary-hover);\n  box-shadow: 0 4px 12px var(--primary-shadow);\n  transform: translateY(-1px);\n}\n\n.btn-secondary {\n  background-color: var(--white);\n  color: var(--slate-700);\n  border: 1px solid var(--border-color);\n  box-shadow: var(--shadow-sm);\n}\n\n.btn-secondary:hover {\n  background-color: var(--slate-50);\n  color: var(--slate-900);\n  border-color: var(--slate-300);\n}\n\n.btn-icon {\n  background: transparent;\n  border: none;\n  color: var(--text-muted);\n  font-size: 16px;\n  cursor: pointer;\n  width: 32px;\n  height: 32px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  border-radius: var(--radius-sm);\n  transition: var(--transition);\n}\n\n.btn-icon:hover {\n  background-color: var(--slate-100);\n  color: var(--slate-900);\n}\n\n/* Statistics Grid */\n.stats-grid {\n  display: grid;\n  grid-template-columns: repeat(5, 1fr);\n  gap: 16px;\n  margin-bottom: 24px;\n}\n\n.stat-card {\n  background-color: var(--bg-card);\n  border: 1px solid var(--border-color);\n  border-radius: var(--radius-lg);\n  padding: 18px 20px;\n  display: flex;\n  align-items: center;\n  gap: 16px;\n  box-shadow: var(--shadow-sm);\n  transition: var(--transition);\n}\n\n.stat-card:hover {\n  border-color: var(--primary-border);\n  box-shadow: var(--shadow-md);\n  transform: translateY(-2px);\n}\n\n.stat-icon {\n  width: 44px;\n  height: 44px;\n  border-radius: var(--radius-md);\n  background-color: var(--primary-light);\n  color: var(--primary);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  font-size: 18px;\n  flex-shrink: 0;\n}\n\n.stat-info {\n  display: flex;\n  flex-direction: column;\n}\n\n.stat-label {\n  font-size: 12px;\n  font-weight: 500;\n  color: var(--text-muted);\n  text-transform: uppercase;\n  letter-spacing: 0.04em;\n}\n\n.stat-value {\n  font-size: 24px;\n  font-weight: 700;\n  color: var(--slate-900);\n  line-height: 1.2;\n  margin-top: 2px;\n}\n\n/* Controls & Filters Bar */\n.controls-card {\n  background-color: var(--bg-card);\n  border: 1px solid var(--border-color);\n  border-radius: var(--radius-lg);\n  padding: 16px 20px;\n  margin-bottom: 24px;\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  gap: 16px;\n  box-shadow: var(--shadow-sm);\n  flex-wrap: wrap;\n}\n\n.search-box {\n  position: relative;\n  flex: 1;\n  min-width: 260px;\n}\n\n.search-box i {\n  position: absolute;\n  left: 14px;\n  top: 50%;\n  transform: translateY(-50%);\n  color: var(--slate-400);\n  font-size: 14px;\n  pointer-events: none;\n}\n\n.search-box input,\n.search-box input[type=\"text\"] {\n  width: 100%;\n  padding: 10px 16px 10px 44px;\n  border-radius: var(--radius-md);\n  border: 1px solid var(--border-color);\n  font-family: inherit;\n  font-size: 14px;\n  color: var(--slate-900);\n  background-color: var(--slate-50);\n  outline: none;\n  transition: var(--transition);\n}\n\n.search-box input:focus,\n.search-box input[type=\"text\"]:focus {\n  background-color: var(--white);\n  border-color: var(--border-focus);\n  box-shadow: 0 0 0 3px var(--primary-shadow);\n}\n\n.filter-group {\n  display: flex;\n  align-items: center;\n  gap: 12px;\n  flex-wrap: wrap;\n}\n\n.select-wrapper {\n  position: relative;\n}\n\n.select-wrapper i {\n  position: absolute;\n  left: 12px;\n  top: 50%;\n  transform: translateY(-50%);\n  color: var(--slate-500);\n  font-size: 13px;\n  pointer-events: none;\n}\n\n.select-wrapper select {\n  padding: 10px 34px 10px 32px;\n  font-family: inherit;\n  font-size: 13px;\n  font-weight: 500;\n  color: var(--slate-700);\n  background-color: var(--slate-50);\n  border: 1px solid var(--border-color);\n  border-radius: var(--radius-md);\n  outline: none;\n  cursor: pointer;\n  appearance: none;\n  -webkit-appearance: none;\n  background-image: url(\"data:image/svg+xml;charset=US-ASCII,%3Csvg%20xmlns%3D%22http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg%22%20width%3D%22292.4%22%20height%3D%22292.4%22%3E%3Cpath%20fill%3D%22%2364748b%22%20d%3D%22M287%2069.4a17.6%2017.6%200%200%200-13-5.4H18.4c-5%200-9.3%201.8-12.9%205.4A17.6%2017.6%200%200%200%200%2082.2c0%205%201.8%209.3%205.4%2012.9l128%20127.9c3.6%203.6%207.8%205.4%2012.8%205.4s9.2-1.8%2012.8-5.4L287%2095c3.5-3.5%205.4-7.8%205.4-12.8%200-5-1.9-9.2-5.5-12.8z%22%2F%3E%3C%2Fsvg%3E\");\n  background-repeat: no-repeat;\n  background-position: right 10px top 50%;\n  background-size: 8px auto;\n  transition: var(--transition);\n}\n\n.select-wrapper select:focus {\n  background-color: var(--white);\n  border-color: var(--border-focus);\n  box-shadow: 0 0 0 3px var(--primary-shadow);\n}\n\n/* Task Section & Table */\n.tasks-section {\n  background-color: var(--bg-card);\n  border: 1px solid var(--border-color);\n  border-radius: var(--radius-lg);\n  box-shadow: var(--shadow-sm);\n  overflow: hidden;\n}\n\n.section-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  padding: 18px 24px;\n  border-bottom: 1px solid var(--border-color);\n}\n\n.section-title {\n  font-size: 17px;\n  font-weight: 700;\n  color: var(--slate-900);\n  display: flex;\n  align-items: center;\n  gap: 10px;\n}\n\n.section-title i {\n  color: var(--primary);\n}\n\n.task-count-pill {\n  font-size: 12px;\n  font-weight: 600;\n  color: var(--slate-600);\n  background-color: var(--slate-100);\n  padding: 4px 10px;\n  border-radius: 20px;\n}\n\n.table-container {\n  overflow-x: auto;\n  position: relative;\n  min-height: 200px;\n}\n\n.tasks-table {\n  width: 100%;\n  border-collapse: collapse;\n  text-align: left;\n}\n\n.tasks-table th {\n  background-color: var(--slate-50);\n  padding: 12px 18px;\n  font-size: 11px;\n  font-weight: 700;\n  text-transform: uppercase;\n  letter-spacing: 0.05em;\n  color: var(--text-muted);\n  border-bottom: 1px solid var(--border-color);\n}\n\n.tasks-table td {\n  padding: 14px 18px;\n  font-size: 14px;\n  color: var(--slate-700);\n  border-bottom: 1px solid var(--border-color);\n  vertical-align: middle;\n}\n\n.tasks-table tbody tr {\n  transition: var(--transition);\n}\n\n.tasks-table tbody tr:hover {\n  background-color: var(--slate-50);\n}\n\n.tasks-table tbody tr:last-child td {\n  border-bottom: none;\n}\n\n.task-title-cell {\n  display: flex;\n  flex-direction: column;\n  gap: 3px;\n}\n\n.task-title-text {\n  font-weight: 600;\n  color: var(--slate-900);\n}\n\n.task-desc-text {\n  font-size: 12px;\n  color: var(--text-muted);\n  line-height: 1.35;\n}\n\n/* Badges (Strict 2-Color Architecture) */\n.badge {\n  display: inline-flex;\n  align-items: center;\n  padding: 4px 10px;\n  border-radius: 6px;\n  font-size: 12px;\n  font-weight: 600;\n  white-space: nowrap;\n}\n\n.badge i {\n  margin-right: 5px;\n  font-size: 11px;\n}\n\n.task-id-badge {\n  font-family: inherit;\n  font-size: 12px;\n  font-weight: 600;\n  color: var(--primary-text);\n  background-color: var(--primary-light);\n  padding: 3px 8px;\n  border-radius: 4px;\n  border: 1px solid var(--primary-border);\n}\n\n.badge-category {\n  background-color: var(--slate-100);\n  color: var(--slate-700);\n  border: 1px solid var(--slate-200);\n}\n\n/* Priority Badges */\n.badge-priority-high {\n  background-color: var(--primary);\n  color: var(--white);\n}\n\n.badge-priority-medium {\n  background-color: var(--primary-light);\n  color: var(--primary-text);\n  border: 1px solid var(--primary-border);\n}\n\n.badge-priority-low {\n  background-color: var(--slate-100);\n  color: var(--slate-600);\n  border: 1px solid var(--slate-200);\n}\n\n/* Status Badges */\n.badge-status-pending {\n  background-color: var(--slate-100);\n  color: var(--slate-700);\n  border: 1px solid var(--slate-200);\n}\n\n.badge-status-in-progress {\n  background-color: var(--primary-light);\n  color: var(--primary-text);\n  border: 1px solid var(--primary-border);\n}\n\n.badge-status-completed {\n  background-color: var(--slate-900);\n  color: var(--white);\n}\n\n/* Action Buttons */\n.action-buttons {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: 8px;\n}\n\n.btn-table-action {\n  padding: 6px 10px;\n  font-size: 12px;\n  font-weight: 600;\n  border-radius: var(--radius-sm);\n  border: 1px solid var(--border-color);\n  background-color: var(--white);\n  color: var(--slate-700);\n  cursor: pointer;\n  transition: var(--transition);\n}\n\n.btn-table-action:hover {\n  background-color: var(--slate-100);\n  color: var(--slate-900);\n  border-color: var(--slate-300);\n}\n\n.btn-toggle-status {\n  background-color: var(--primary-light);\n  color: var(--primary-text);\n  border-color: var(--primary-border);\n}\n\n.btn-toggle-status:hover {\n  background-color: var(--primary);\n  color: var(--white);\n  border-color: var(--primary);\n}\n\n.btn-delete-row:hover {\n  background-color: var(--slate-900);\n  color: var(--white);\n  border-color: var(--slate-900);\n}\n\n/* Empty & Loading States */\n.empty-state {\n  text-align: center;\n  padding: 60px 24px;\n}\n\n.empty-icon {\n  font-size: 42px;\n  color: var(--slate-300);\n  margin-bottom: 16px;\n}\n\n.empty-state h3 {\n  font-size: 18px;\n  font-weight: 700;\n  color: var(--slate-900);\n  margin-bottom: 6px;\n}\n\n.empty-state p {\n  font-size: 14px;\n  color: var(--text-muted);\n  margin-bottom: 20px;\n}\n\n.loading-state {\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n  padding: 60px 24px;\n  gap: 16px;\n  color: var(--text-muted);\n  font-size: 14px;\n}\n\n.spinner {\n  width: 32px;\n  height: 32px;\n  border: 3px solid var(--slate-200);\n  border-top-color: var(--primary);\n  border-radius: 50%;\n  animation: spin 0.8s linear infinite;\n}\n\n@keyframes spin {\n  to { transform: rotate(360deg); }\n}\n\n/* Modals */\n.modal-backdrop {\n  position: fixed;\n  inset: 0;\n  background-color: rgba(15, 23, 42, 0.45);\n  backdrop-filter: blur(4px);\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  z-index: 1000;\n  padding: 20px;\n}\n\n.modal-card {\n  background-color: var(--white);\n  border-radius: var(--radius-xl);\n  width: 100%;\n  max-width: 540px;\n  box-shadow: var(--shadow-modal);\n  border: 1px solid var(--border-color);\n  animation: modalEnter 0.2s ease-out;\n  overflow: hidden;\n}\n\n.modal-sm {\n  max-width: 420px;\n}\n\n@keyframes modalEnter {\n  from {\n    opacity: 0;\n    transform: scale(0.96) translateY(-10px);\n  }\n  to {\n    opacity: 1;\n    transform: scale(1) translateY(0);\n  }\n}\n\n.modal-header {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  padding: 20px 24px;\n  border-bottom: 1px solid var(--border-color);\n}\n\n.modal-header h3 {\n  font-size: 18px;\n  font-weight: 700;\n  color: var(--slate-900);\n  display: flex;\n  align-items: center;\n  gap: 10px;\n}\n\n.modal-header h3 i {\n  color: var(--primary);\n}\n\n.modal-body {\n  padding: 24px;\n  font-size: 14px;\n  color: var(--slate-700);\n  line-height: 1.6;\n}\n\n.delete-task-preview {\n  margin-top: 12px;\n  padding: 10px 14px;\n  background-color: var(--slate-50);\n  border: 1px solid var(--border-color);\n  border-radius: var(--radius-sm);\n  font-weight: 600;\n  color: var(--slate-900);\n}\n\nform {\n  padding: 24px;\n}\n\n.form-group {\n  margin-bottom: 18px;\n}\n\n.form-row {\n  display: grid;\n  grid-template-columns: 1fr 1fr;\n  gap: 16px;\n}\n\nlabel {\n  display: block;\n  font-size: 13px;\n  font-weight: 600;\n  color: var(--slate-700);\n  margin-bottom: 6px;\n}\n\n.required {\n  color: var(--primary);\n}\n\nform input[type=\"text\"],\nform input[type=\"date\"],\nform select,\nform textarea {\n  width: 100%;\n  padding: 10px 14px;\n  border: 1px solid var(--border-color);\n  border-radius: var(--radius-md);\n  font-family: inherit;\n  font-size: 14px;\n  color: var(--slate-900);\n  background-color: var(--white);\n  outline: none;\n  transition: var(--transition);\n}\n\nform input:focus,\nform select:focus,\nform textarea:focus {\n  border-color: var(--border-focus);\n  box-shadow: 0 0 0 3px var(--primary-shadow);\n}\n\ntextarea {\n  resize: vertical;\n  min-height: 80px;\n}\n\n.modal-footer {\n  display: flex;\n  justify-content: flex-end;\n  gap: 12px;\n  padding: 18px 24px;\n  background-color: var(--slate-50);\n  border-top: 1px solid var(--border-color);\n}\n\n/* Toast Notifications */\n.toast-container {\n  position: fixed;\n  bottom: 24px;\n  right: 24px;\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n  z-index: 2000;\n}\n\n.toast {\n  background-color: var(--slate-900);\n  color: var(--white);\n  padding: 12px 18px;\n  border-radius: var(--radius-md);\n  font-size: 13px;\n  font-weight: 500;\n  box-shadow: var(--shadow-lg);\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  animation: toastIn 0.25s ease-out;\n  border-left: 4px solid var(--primary);\n}\n\n@keyframes toastIn {\n  from {\n    opacity: 0;\n    transform: translateY(12px);\n  }\n  to {\n    opacity: 1;\n    transform: translateY(0);\n  }\n}\n\n/* Responsive adjustments */\n@media (max-width: 900px) {\n  .stats-grid {\n    grid-template-columns: repeat(2, 1fr);\n  }\n  .stat-card:last-child {\n    grid-column: span 2;\n  }\n}\n\n@media (max-width: 640px) {\n  .stats-grid {\n    grid-template-columns: 1fr;\n  }\n  .stat-card:last-child {\n    grid-column: auto;\n  }\n  .app-header {\n    flex-direction: column;\n    align-items: flex-start;\n  }\n  .header-actions {\n    width: 100%;\n    justify-content: space-between;\n  }\n  .form-row {\n    grid-template-columns: 1fr;\n  }\n}\n";
const SCRIPT_JS = "/**\n * Student Task Management Application - Client-Side Controller\n * Connects with Cloudflare Workers REST API & Workers KV\n */\n\n// Application State\nlet tasks = [];\nlet pendingDeleteId = null;\nconst API_BASE = '/api/tasks';\n\n// DOM Elements\nconst taskTableBody = document.getElementById('tasks-table-body');\nconst emptyState = document.getElementById('empty-state');\nconst loadingState = document.getElementById('loading-state');\nconst searchInput = document.getElementById('task-search-input');\nconst filterStatus = document.getElementById('filter-status');\nconst filterPriority = document.getElementById('filter-priority');\nconst filterSort = document.getElementById('filter-sort');\nconst refreshBtn = document.getElementById('btn-refresh-tasks');\nconst showingCount = document.getElementById('showing-task-count');\nconst seedBtn = document.getElementById('btn-seed-sample-tasks');\n\n// Modal Elements\nconst taskModal = document.getElementById('task-modal');\nconst taskForm = document.getElementById('task-form');\nconst modalTitle = document.getElementById('modal-title');\nconst btnOpenCreateModal = document.getElementById('btn-open-create-modal');\nconst btnCloseModal = document.getElementById('btn-close-modal');\nconst btnCancelModal = document.getElementById('btn-cancel-modal');\nconst formTaskId = document.getElementById('form-task-id');\nconst formTaskTitle = document.getElementById('form-task-title');\nconst formTaskPriority = document.getElementById('form-task-priority');\nconst formTaskStatus = document.getElementById('form-task-status');\nconst formTaskCategory = document.getElementById('form-task-category');\nconst formTaskDue = document.getElementById('form-task-due');\nconst formTaskDesc = document.getElementById('form-task-description');\nconst btnSubmitText = document.getElementById('btn-submit-text');\n\n// Delete Modal Elements\nconst deleteModal = document.getElementById('delete-modal');\nconst btnCloseDeleteModal = document.getElementById('btn-close-delete-modal');\nconst btnCancelDelete = document.getElementById('btn-cancel-delete');\nconst btnConfirmDelete = document.getElementById('btn-confirm-delete');\nconst deleteTaskPreview = document.getElementById('delete-task-preview');\n\n// Stat Counters\nconst statTotal = document.getElementById('stat-total-count');\nconst statPending = document.getElementById('stat-pending-count');\nconst statInProgress = document.getElementById('stat-in-progress-count');\nconst statCompleted = document.getElementById('stat-completed-count');\nconst statHigh = document.getElementById('stat-high-count');\nconst backendStatusText = document.getElementById('backend-status-text');\n\n// Initial Setup\ndocument.addEventListener('DOMContentLoaded', () => {\n  initEventListeners();\n  loadTasks();\n});\n\nfunction initEventListeners() {\n  btnOpenCreateModal.addEventListener('click', () => openCreateModal());\n  btnCloseModal.addEventListener('click', closeModal);\n  btnCancelModal.addEventListener('click', closeModal);\n  \n  taskForm.addEventListener('submit', handleTaskFormSubmit);\n\n  btnCloseDeleteModal.addEventListener('click', closeDeleteModal);\n  btnCancelDelete.addEventListener('click', closeDeleteModal);\n  btnConfirmDelete.addEventListener('click', confirmDeleteTask);\n\n  searchInput.addEventListener('input', renderTasks);\n  filterStatus.addEventListener('change', renderTasks);\n  filterPriority.addEventListener('change', renderTasks);\n  filterSort.addEventListener('change', renderTasks);\n  refreshBtn.addEventListener('click', () => {\n    showToast('Refreshing task list...', 'info');\n    loadTasks();\n  });\n\n  if (seedBtn) {\n    seedBtn.addEventListener('click', seedSampleTasks);\n  }\n\n  // Close modals on clicking backdrop\n  window.addEventListener('click', (e) => {\n    if (e.target === taskModal) closeModal();\n    if (e.target === deleteModal) closeDeleteModal();\n  });\n}\n\n/**\n * Fetch tasks from API (or fallback if running locally)\n */\nasync function loadTasks() {\n  showLoading(true);\n  try {\n    const response = await fetch(API_BASE);\n    if (!response.ok) {\n      throw new Error(`API responded with status: ${response.status}`);\n    }\n    const data = await response.json();\n    tasks = Array.isArray(data) ? data : (data.tasks || []);\n    if (backendStatusText) backendStatusText.textContent = 'Live';\n    renderTasks();\n  } catch (err) {\n    console.warn('API unavailable, utilizing local storage:', err.message);\n    if (backendStatusText) backendStatusText.textContent = 'Local Mode';\n    // Fallback to localStorage so UI is 100% functional during local testing\n    const saved = localStorage.getItem('student_tasks_db');\n    if (saved) {\n      try {\n        tasks = JSON.parse(saved);\n        if (tasks.some(t => (t.title && (t.title.includes('Terraform') || t.title.includes('Cloud Computing'))) || \n                            (t.description && (t.description.includes('IaC') || t.description.includes('Cloudflare'))))) {\n          tasks = getInitialSampleTasks();\n          saveToLocalStorage();\n        }\n      } catch (e) {\n        tasks = getInitialSampleTasks();\n      }\n    } else {\n      tasks = getInitialSampleTasks();\n      saveToLocalStorage();\n    }\n    renderTasks();\n  } finally {\n    showLoading(false);\n  }\n}\n\n/**\n * Persist task updates (POST or PUT)\n */\nasync function handleTaskFormSubmit(e) {\n  e.preventDefault();\n\n  const id = formTaskId.value.trim();\n  const taskPayload = {\n    title: formTaskTitle.value.trim(),\n    priority: formTaskPriority.value,\n    status: formTaskStatus.value,\n    category: formTaskCategory.value,\n    dueDate: formTaskDue.value,\n    description: formTaskDesc.value.trim()\n  };\n\n  try {\n    if (id) {\n      // Update Task (PUT /api/tasks/{id})\n      taskPayload.id = id;\n      try {\n        const res = await fetch(`${API_BASE}/${id}`, {\n          method: 'PUT',\n          headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify(taskPayload)\n        });\n        if (res.ok) {\n          const updated = await res.json();\n          updateLocalTask(updated);\n        } else {\n          fallbackUpdateLocalTask(id, taskPayload);\n        }\n      } catch {\n        fallbackUpdateLocalTask(id, taskPayload);\n      }\n      showToast(`Task ${id} updated successfully!`, 'success');\n    } else {\n      // Create Task (POST /api/tasks)\n      try {\n        const res = await fetch(API_BASE, {\n          method: 'POST',\n          headers: { 'Content-Type': 'application/json' },\n          body: JSON.stringify(taskPayload)\n        });\n        if (res.ok) {\n          const created = await res.json();\n          tasks.unshift(created);\n        } else {\n          fallbackCreateLocalTask(taskPayload);\n        }\n      } catch {\n        fallbackCreateLocalTask(taskPayload);\n      }\n      showToast('New academic task created successfully!', 'success');\n    }\n\n    saveToLocalStorage();\n    renderTasks();\n    closeModal();\n  } catch (err) {\n    showToast(`Error saving task: ${err.message}`, 'error');\n  }\n}\n\nfunction fallbackCreateLocalTask(payload) {\n  const nextNum = tasks.length + 101;\n  const newId = `T${nextNum}`;\n  const newTask = {\n    id: newId,\n    ...payload,\n    createdAt: new Date().toISOString()\n  };\n  tasks.unshift(newTask);\n}\n\nfunction fallbackUpdateLocalTask(id, payload) {\n  const idx = tasks.findIndex(t => t.id === id);\n  if (idx !== -1) {\n    tasks[idx] = { ...tasks[idx], ...payload, updatedAt: new Date().toISOString() };\n  }\n}\n\nfunction updateLocalTask(updated) {\n  const idx = tasks.findIndex(t => t.id === updated.id);\n  if (idx !== -1) {\n    tasks[idx] = updated;\n  } else {\n    tasks.unshift(updated);\n  }\n}\n\n/**\n * Quick Toggle Status (Test Case 3 requirement)\n */\nasync function toggleTaskStatus(id) {\n  const task = tasks.find(t => t.id === id);\n  if (!task) return;\n\n  let newStatus = 'Pending';\n  if (task.status === 'Pending') newStatus = 'In Progress';\n  else if (task.status === 'In Progress') newStatus = 'Completed';\n  else newStatus = 'Pending';\n\n  const updatedPayload = { ...task, status: newStatus };\n\n  try {\n    const res = await fetch(`${API_BASE}/${id}`, {\n      method: 'PUT',\n      headers: { 'Content-Type': 'application/json' },\n      body: JSON.stringify(updatedPayload)\n    });\n    if (res.ok) {\n      const data = await res.json();\n      updateLocalTask(data);\n    } else {\n      task.status = newStatus;\n    }\n  } catch {\n    task.status = newStatus;\n  }\n\n  saveToLocalStorage();\n  renderTasks();\n  showToast(`Task ${id} status updated to ${newStatus}`, 'success');\n}\n\n/**\n * Delete Task (DELETE /api/tasks/{id})\n */\nfunction requestDeleteTask(id) {\n  const task = tasks.find(t => t.id === id);\n  if (!task) return;\n  pendingDeleteId = id;\n  deleteTaskPreview.textContent = `${task.id}: ${task.title}`;\n  deleteModal.style.display = 'flex';\n}\n\nasync function confirmDeleteTask() {\n  if (!pendingDeleteId) return;\n  const id = pendingDeleteId;\n\n  try {\n    const res = await fetch(`${API_BASE}/${id}`, { method: 'DELETE' });\n    if (!res.ok && res.status !== 404) {\n      console.warn('API deletion returned non-OK status');\n    }\n  } catch (e) {\n    console.warn('API DELETE fallback:', e.message);\n  }\n\n  tasks = tasks.filter(t => t.id !== id);\n  saveToLocalStorage();\n  renderTasks();\n  closeDeleteModal();\n  showToast(`Task ${id} deleted successfully.`, 'info');\n}\n\n/**\n * Filter, Sort, and Render Tasks\n */\nfunction renderTasks() {\n  const searchQuery = searchInput.value.toLowerCase().trim();\n  const statusFilterVal = filterStatus.value;\n  const priorityFilterVal = filterPriority.value;\n  const sortVal = filterSort.value;\n\n  // Filter\n  let filtered = tasks.filter(task => {\n    const matchesSearch = !searchQuery || \n      (task.title && task.title.toLowerCase().includes(searchQuery)) ||\n      (task.id && task.id.toLowerCase().includes(searchQuery)) ||\n      (task.category && task.category.toLowerCase().includes(searchQuery)) ||\n      (task.description && task.description.toLowerCase().includes(searchQuery));\n\n    const matchesStatus = statusFilterVal === 'all' || task.status === statusFilterVal;\n    const matchesPriority = priorityFilterVal === 'all' || task.priority === priorityFilterVal;\n\n    return matchesSearch && matchesStatus && matchesPriority;\n  });\n\n  // Sort\n  const priorityWeight = { High: 3, Medium: 2, Low: 1 };\n  filtered.sort((a, b) => {\n    if (sortVal === 'date-desc') {\n      return new Date(b.createdAt || 0) - new Date(a.createdAt || 0);\n    } else if (sortVal === 'date-asc') {\n      return new Date(a.createdAt || 0) - new Date(b.createdAt || 0);\n    } else if (sortVal === 'priority-desc') {\n      return (priorityWeight[b.priority] || 0) - (priorityWeight[a.priority] || 0);\n    } else if (sortVal === 'priority-asc') {\n      return (priorityWeight[a.priority] || 0) - (priorityWeight[b.priority] || 0);\n    }\n    return 0;\n  });\n\n  // Render Table\n  taskTableBody.innerHTML = '';\n  if (filtered.length === 0) {\n    emptyState.style.display = 'block';\n  } else {\n    emptyState.style.display = 'none';\n    filtered.forEach(task => {\n      const row = document.createElement('tr');\n      row.id = `task-row-${task.id}`;\n\n      const createdDateFormatted = task.createdAt \n        ? new Date(task.createdAt).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' })\n        : 'Recent';\n\n      const priorityClass = `badge-priority-${(task.priority || 'medium').toLowerCase()}`;\n      const statusClass = `badge-status-${(task.status || 'pending').toLowerCase().replace(' ', '-')}`;\n\n      row.innerHTML = `\n        <td>\n          <span class=\"task-id-badge\">${escapeHtml(task.id)}</span>\n        </td>\n        <td>\n          <div class=\"task-title-cell\">\n            <span class=\"task-title-text\">${escapeHtml(task.title)}</span>\n            ${task.description ? `<span class=\"task-desc-text\">${escapeHtml(task.description)}</span>` : ''}\n          </div>\n        </td>\n        <td>\n          <span class=\"badge badge-category\">\n            <i class=\"fa-solid fa-tag\"></i> ${escapeHtml(task.category || 'General')}\n          </span>\n        </td>\n        <td>\n          <span class=\"badge ${priorityClass}\">\n            <i class=\"fa-solid fa-flag\"></i> ${escapeHtml(task.priority || 'Medium')}\n          </span>\n        </td>\n        <td>\n          <span class=\"badge ${statusClass}\">\n            ${getStatusIcon(task.status)} ${escapeHtml(task.status || 'Pending')}\n          </span>\n        </td>\n        <td style=\"color: var(--text-dim); font-size: 0.85rem;\">\n          ${createdDateFormatted}\n        </td>\n        <td>\n          <div class=\"action-buttons\">\n            <button class=\"btn-table-action btn-toggle-status\" onclick=\"toggleTaskStatus('${task.id}')\" title=\"Advance status\">\n              <i class=\"fa-solid fa-check\"></i>\n              <span>Status</span>\n            </button>\n            <button class=\"btn-table-action\" onclick=\"openEditModal('${task.id}')\" title=\"Edit details\">\n              <i class=\"fa-solid fa-pen\"></i>\n            </button>\n            <button class=\"btn-table-action btn-delete-row\" onclick=\"requestDeleteTask('${task.id}')\" title=\"Delete from KV\">\n              <i class=\"fa-regular fa-trash-can\"></i>\n            </button>\n          </div>\n        </td>\n      `;\n      taskTableBody.appendChild(row);\n    });\n  }\n\n  // Update Counters\n  updateStatistics();\n  showingCount.textContent = `Showing ${filtered.length} of ${tasks.length} tasks`;\n}\n\nfunction updateStatistics() {\n  const total = tasks.length;\n  const pending = tasks.filter(t => t.status === 'Pending').length;\n  const inProgress = tasks.filter(t => t.status === 'In Progress').length;\n  const completed = tasks.filter(t => t.status === 'Completed').length;\n  const high = tasks.filter(t => t.priority === 'High').length;\n\n  statTotal.textContent = total;\n  statPending.textContent = pending;\n  statInProgress.textContent = inProgress;\n  statCompleted.textContent = completed;\n  statHigh.textContent = high;\n}\n\nfunction getStatusIcon(status) {\n  if (status === 'Completed') return '<i class=\"fa-solid fa-circle-check\"></i>';\n  if (status === 'In Progress') return '<i class=\"fa-solid fa-arrows-rotate\"></i>';\n  return '<i class=\"fa-solid fa-clock\"></i>';\n}\n\nfunction openCreateModal() {\n  taskForm.reset();\n  formTaskId.value = '';\n  modalTitle.innerHTML = '<i class=\"fa-solid fa-pen-to-square\"></i> Create New Task';\n  btnSubmitText.textContent = 'Save Task';\n  taskModal.style.display = 'flex';\n  formTaskTitle.focus();\n}\n\nfunction openEditModal(id) {\n  const task = tasks.find(t => t.id === id);\n  if (!task) return;\n\n  formTaskId.value = task.id;\n  formTaskTitle.value = task.title || '';\n  formTaskPriority.value = task.priority || 'Medium';\n  formTaskStatus.value = task.status || 'Pending';\n  formTaskCategory.value = task.category || 'General';\n  formTaskDue.value = task.dueDate || '';\n  formTaskDesc.value = task.description || '';\n\n  modalTitle.innerHTML = `<i class=\"fa-solid fa-pen-to-square\"></i> Edit Task (${escapeHtml(task.id)})`;\n  btnSubmitText.textContent = 'Update Task';\n  taskModal.style.display = 'flex';\n  formTaskTitle.focus();\n}\n\nfunction closeModal() {\n  taskModal.style.display = 'none';\n}\n\nfunction closeDeleteModal() {\n  deleteModal.style.display = 'none';\n  pendingDeleteId = null;\n}\n\nfunction showLoading(show) {\n  loadingState.style.display = show ? 'flex' : 'none';\n}\n\nfunction saveToLocalStorage() {\n  try {\n    localStorage.setItem('student_tasks_db', JSON.stringify(tasks));\n  } catch (e) {\n    console.error('Local storage quota exceeded', e);\n  }\n}\n\nfunction seedSampleTasks() {\n  tasks = getInitialSampleTasks();\n  saveToLocalStorage();\n  renderTasks();\n  showToast('Academic sample tasks loaded into system!', 'success');\n}\n\nfunction getInitialSampleTasks() {\n  return [\n    {\n      id: \"T101\",\n      title: \"Complete Operating Systems Lab Assignment\",\n      priority: \"High\",\n      status: \"Pending\",\n      category: \"Assignment\",\n      dueDate: \"2026-10-25\",\n      description: \"Implement CPU scheduling algorithms and multithreaded synchronization in C++.\",\n      createdAt: new Date(Date.now() - 3600000 * 24 * 3).toISOString()\n    },\n    {\n      id: \"T102\",\n      title: \"Prepare Final Year Seminar Presentation\",\n      priority: \"High\",\n      status: \"In Progress\",\n      category: \"Presentation\",\n      dueDate: \"2026-10-30\",\n      description: \"Prepare slides covering project methodology, architecture, and live demonstration.\",\n      createdAt: new Date(Date.now() - 3600000 * 24 * 2).toISOString()\n    },\n    {\n      id: \"T103\",\n      title: \"Submit Term Project Documentation\",\n      priority: \"Medium\",\n      status: \"Completed\",\n      category: \"Project\",\n      dueDate: \"2026-10-18\",\n      description: \"Format and submit final report document according to department guidelines.\",\n      createdAt: new Date(Date.now() - 3600000 * 24 * 5).toISOString()\n    },\n    {\n      id: \"T104\",\n      title: \"Database Management Final Exam Prep\",\n      priority: \"High\",\n      status: \"Pending\",\n      category: \"Examination\",\n      dueDate: \"2026-11-02\",\n      description: \"Review normalization, indexing, query optimization, and ACID transaction properties.\",\n      createdAt: new Date(Date.now() - 3600000 * 24 * 1).toISOString()\n    },\n    {\n      id: \"T105\",\n      title: \"Computer Networks Packet Tracer Lab\",\n      priority: \"Low\",\n      status: \"Completed\",\n      category: \"Lab Work\",\n      dueDate: \"2026-10-15\",\n      description: \"Design and verify VLAN routing and subnet topologies using packet analyzer.\",\n      createdAt: new Date(Date.now() - 3600000 * 24 * 6).toISOString()\n    }\n  ];\n}\n\nfunction showToast(message, type = 'info') {\n  const container = document.getElementById('toast-container');\n  const toast = document.createElement('div');\n  toast.className = `toast toast-${type}`;\n\n  let icon = 'fa-info-circle';\n  if (type === 'success') icon = 'fa-circle-check';\n  if (type === 'error') icon = 'fa-circle-exclamation';\n\n  toast.innerHTML = `\n    <i class=\"fa-solid ${icon}\"></i>\n    <span>${escapeHtml(message)}</span>\n  `;\n\n  container.appendChild(toast);\n  setTimeout(() => {\n    toast.style.opacity = '0';\n    toast.style.transform = 'translateY(10px)';\n    setTimeout(() => toast.remove(), 300);\n  }, 3500);\n}\n\nfunction escapeHtml(str) {\n  if (!str) return '';\n  return String(str)\n    .replace(/&/g, '&amp;')\n    .replace(/</g, '&lt;')\n    .replace(/>/g, '&gt;')\n    .replace(/\"/g, '&quot;')\n    .replace(/'/g, '&#039;');\n}\n\n// Make functions accessible from onclick table buttons\nwindow.toggleTaskStatus = toggleTaskStatus;\nwindow.openEditModal = openEditModal;\nwindow.requestDeleteTask = requestDeleteTask;\n";
